];

export async function listTools() {
  return TOOLS;
}

function encodeCursor(startIndex) {
  return Buffer.from(JSON.stringify({ i: startIndex }), 'utf8').toString('base64url');
}

function decodeCursor(cursor) {
  let parsed;
  try {
    const raw = Buffer.from(cursor, 'base64url').toString('utf8');
    parsed = JSON.parse(raw);
  } catch {
    throw new Error('Invalid cursor');
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new Error('Invalid cursor');
  }
  const keys = Object.keys(parsed);
  if (keys.length !== 1 || keys[0] !== 'i' || !Number.isInteger(parsed.i) || parsed.i < 0 || parsed.i > events.length) {
    throw new Error('Invalid cursor');
  }
  return parsed.i;
}

function validateArgs(args) {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments');
  }
  const allowed = new Set(['cursor', 'page_size']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unknown field: ${key}`);
    }
  }
  if ('cursor' in args) {
    if (typeof args.cursor !== 'string' || args.cursor.length === 0) {
      throw new Error('Invalid cursor');
    }
  }
  if ('page_size' in args) {
    if (typeof args.page_size !== 'number' || !Number.isInteger(args.page_size) || args.page_size < 1 || args.page_size > 3) {
      throw new Error('Invalid page_size');
    }
  }
}

export async function callTool(name, args) {
  if (name !== 'events_list') {
    throw new Error(`Unknown tool: ${name}`);
  }
  args = args || {};
  validateArgs(args);

  const pageSize = 'page_size' in args ? args.page_size : 2;
  const startIndex = args.cursor ? decodeCursor(args.cursor) : 0;

